SELECT 
      array(to_variant_object(map('elementId', CAST(concat('User:', CAST(v0.user_id AS STRING), '-') AS VARIANT), 'labels', CAST(array('User') AS VARIANT), 'properties', CAST(to_variant_object(map_filter(map('age', CAST(v0.age AS VARIANT), 'city', CAST(v0.city AS VARIANT), 'country', CAST(v0.country AS VARIANT), 'email', CAST(v0.email_address AS VARIANT), 'is_active', CAST(v0.is_active AS VARIANT), 'name', CAST(v0.full_name AS VARIANT), 'registration_date', CAST(v0.registration_date AS VARIANT), 'user_id', CAST(v0.user_id AS VARIANT)), (__k, __v) -> __v IS NOT NULL)) AS VARIANT))), to_variant_object(map('elementId', CAST(concat('FOLLOWS:', CAST(v1.follower_id AS STRING), '->', CAST(v1.followed_id AS STRING), '-') AS VARIANT), 'startNodeElementId', CAST(concat('User:', CAST(v1.follower_id AS STRING), '-') AS VARIANT), 'endNodeElementId', CAST(concat('User:', CAST(v1.followed_id AS STRING), '-') AS VARIANT), 'type', CAST('FOLLOWS' AS VARIANT), 'properties', CAST(to_variant_object(map_filter(map('follow_date', CAST(v1.follow_date AS VARIANT)), (__k, __v) -> __v IS NOT NULL)) AS VARIANT))), to_variant_object(map('elementId', CAST(concat('User:', CAST(v2.user_id AS STRING), '-') AS VARIANT), 'labels', CAST(array('User') AS VARIANT), 'properties', CAST(to_variant_object(map_filter(map('age', CAST(v2.age AS VARIANT), 'city', CAST(v2.city AS VARIANT), 'country', CAST(v2.country AS VARIANT), 'email', CAST(v2.email_address AS VARIANT), 'is_active', CAST(v2.is_active AS VARIANT), 'name', CAST(v2.full_name AS VARIANT), 'registration_date', CAST(v2.registration_date AS VARIANT), 'user_id', CAST(v2.user_id AS VARIANT)), (__k, __v) -> __v IS NOT NULL)) AS VARIANT)))) AS `p`
FROM test_integration.users_test AS v0
JOIN test_integration.user_follows_test AS v1 ON v1.follower_id = v0.user_id
JOIN test_integration.users_test AS v2 ON v1.followed_id = v2.user_id
LIMIT 5